INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(12701, 'Job 34:6', 'Job', 34, 6, '&nbsp;زۀ بې‌ګناه يم خو دروغژن ګڼلے شم، په ما کښې څۀ غلطى نشته، خو زما د زخم علاج نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12702, 'Job 34:7', 'Job', 34, 7, '&nbsp;د ايُوب په شان څوک شته، چې په چا کښې زره غوندې ادب هم نۀ وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12703, 'Job 34:8', 'Job', 34, 8, '&nbsp;چې هغه د بدعملو سره ملګرتيا کوى او د بدمعاشانو سره ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12704, 'Job 34:9', 'Job', 34, 9, '&nbsp;نو هغۀ دا هم وئيلى دى چې، ”د خُدائ پاک د راضى کولو څۀ فائده ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12705, 'Job 34:10', 'Job', 34, 10, '&nbsp;نو چې څوک عقل لرئ نو زما خبره واورئ، هر چا ته پته ده چې خُدائ پاک بدى نۀ کوى، او د قادر خُدائ دپاره ممکن نۀ دى چې هغه غلطى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12706, 'Job 34:11', 'Job', 34, 11, '&nbsp;ځکه چې هغه د عملونو په مطابق خلقو له بدله ورکوى، او هغه شان سلوک ورسره کوى چې څنګه يې حقدار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12707, 'Job 34:12', 'Job', 34, 12, '&nbsp;بې‌شکه، خُدائ پاک به بد عمل نۀ کوى، او قادر خُدائ د هيچا سره بې‌اِنصافى نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12708, 'Job 34:13', 'Job', 34, 13, '&nbsp;هغۀ له د زمکې اختيار چا ورکړے دے، او دا ټوله دُنيا په خپل ځائ چا لګولې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12709, 'Job 34:14', 'Job', 34, 14, '&nbsp;کۀ خُدائ پاک د خلقو نه روح واخلى، او د ژوند ساه ترې نه واخلى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12710, 'Job 34:15', 'Job', 34, 15, '&nbsp;ټول انسانان به ختم شى، او ټول بنى آدم به خاورو ته واپس کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12711, 'Job 34:16', 'Job', 34, 16, '&nbsp;کۀ تاسو پوهه لرئ، نو دا خبره واورئ، زۀ چې څۀ وايم نو هغې ته غوږ کېږدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12712, 'Job 34:17', 'Job', 34, 17, '&nbsp;چې خُدائ پاک پخپله اِنصاف نۀ کوى نو بيا هغه څنګه دُنيا چلولے شى؟ تاسو به هغه لويه هستى رد کوئ څوک چې صادق دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12713, 'Job 34:18', 'Job', 34, 18, '&nbsp;څوک چې بادشاه ته وائى چې تۀ بې‌کاره يې، او مشر ته وائى چې تۀ بدعمله يې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12714, 'Job 34:19', 'Job', 34, 19, '&nbsp;څوک چې د حکمرانانو طرفدارى نۀ کوى، او د مالدارو خلقو طرفدارى د غريبانانو نه زياته نۀ کوى، ځکه چې ټول هغۀ پېدا کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12715, 'Job 34:20', 'Job', 34, 20, '&nbsp;يو کس د شپې اچانک مړ کېدے شى، خُدائ پاک خلق ووهى او هغوئ هلاک شى، خُدائ پاک طاقتور خلق هم په آسانۍ سره وژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12716, 'Job 34:21', 'Job', 34, 21, '&nbsp;ځکه چې د هغۀ نظر د بنى آدم په عمل باندې دے، او هغه د هغوئ هر قدم ته ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12717, 'Job 34:22', 'Job', 34, 22, '&nbsp;داسې تکه توره تيارۀ نشته چرته چې بدعمله خلق خپل ځانونه د هغۀ نه پټ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12718, 'Job 34:23', 'Job', 34, 23, '&nbsp;مونږ وخت نۀ مقرروو چې کله به د خُدائ پاک په وړاندې د عدالت دپاره راځو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12719, 'Job 34:24', 'Job', 34, 24, '&nbsp;هغه د تپوس نه بغېر طاقتور راګزار کړى، او د هغوئ په ځائ کښې نور مقرر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12720, 'Job 34:25', 'Job', 34, 25, '&nbsp;هغه د هغوئ په کارونو خبر دے، هغه يې په شپه کښې لرې کړى او هغوئ تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12721, 'Job 34:26', 'Job', 34, 26, '&nbsp;د هغوئ د بدعملۍ په وجه يې تباه کړى چې د نورو دپاره د عبرت سبب جوړ شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12722, 'Job 34:27', 'Job', 34, 27, '&nbsp;ځکه چې هغوئ د هغۀ د تابعدارۍ نه اوړى، او د هغۀ په حُکمونو باندې عمل نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12723, 'Job 34:28', 'Job', 34, 28, '&nbsp;نو هغوئ غريبانان فرياد کولو ته جوړ کړل، چې دا فرياد خُدائ پاک ته ورسيږى. او هغۀ د ضرورتمندو خلقو فرياد واورېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12724, 'Job 34:29', 'Job', 34, 29, '&nbsp;کۀ خُدائ پاک خاموش وى، نو څوک ورباندې اِعتراض کولے شى څۀ؟ کله چې هغه پناه شى، نو څوک يې ليدلے شى، کۀ هغه يو کس وى او کۀ قوم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12725, 'Job 34:30', 'Job', 34, 30, '&nbsp;نو چې داسې د خُدائ پاک نه منکر خلق حکومت ونۀ کړى، او چې هغوئ خلق دوکه نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12726, 'Job 34:31', 'Job', 34, 31, '&nbsp;خلق خُدائ پاک ته ولې نۀ وائى چې، ”مونږ ګناه کړې ده، خو مونږ به نوره ګناه نۀ کوُو“؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12727, 'Job 34:32', 'Job', 34, 32, '&nbsp;يا، ”ما چې کومه بدعملى کړې وى نو هغه ما ته وښايه، کۀ ما غلطى کړې وى، نو فوراً به يې پرېږدم“؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12728, 'Job 34:33', 'Job', 34, 33, '&nbsp;خُدائ پاک به ستا د خوښې دپاره خپل اِنصاف پرېږدى؟ خو تا هغه رد کړے دے. دا زما نه بلکې ستا فېصله ده، مونږ ته اوس ووايه چې ستا خيال څۀ دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12729, 'Job 34:34', 'Job', 34, 34, '&nbsp;چې څوک پوهه لرى نو هغوئ به ما ته ووائى، او هغه عقلمند چې ما ته غوږ ږدى نو هغوئ به ووائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12730, 'Job 34:35', 'Job', 34, 35, '&nbsp;”ايُوب د جهالت خبرې کوى، د هغۀ خبرې د کم عقلتوب نه ډکې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12731, 'Job 34:36', 'Job', 34, 36, '&nbsp;ايُوب دې عدالت ته راوستلے شى او غټى نه غټه سزا دې ورکړے شى، ځکه چې هغه د بدعمله سړى په شان خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12732, 'Job 34:37', 'Job', 34, 37, '&nbsp;ځکه چې هغه د سرکشۍ سره ګناه کوى، هغه ګستاخ دے، او هغه د خُدائ پاک خِلاف ډېرې خبرې کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12733, 'Job 35:1', 'Job', 35, 1, '&nbsp;اليهُو خپله خبره جارى وساتله او وې وئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12734, 'Job 35:2', 'Job', 35, 2, '&nbsp;”ستا په خيال دا دعوىٰ به صحيح وى، چې تۀ وائى چې د خُدائ پاک په نظر کښې زۀ صادق يم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12735, 'Job 35:3', 'Job', 35, 3, '&nbsp;خو تۀ بيا هم د هغۀ نه تپوس کوې چې په دې کښې زما څۀ ګټه ده، او د ګناه د نۀ کولو په وجه ما ته څۀ فائده مِلاو شوې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12736, 'Job 35:4', 'Job', 35, 4, '&nbsp;زۀ به تا او ستا ملګرو له جواب درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12737, 'Job 35:5', 'Job', 35, 5, '&nbsp;آسمان ته نظر وکړه او وګوره، هغه وريځې وګوره، کومې چې ستا نه اوچتې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12738, 'Job 35:6', 'Job', 35, 6, '&nbsp;کۀ تا ګناه کړې وى، نو په خُدائ پاک باندې څۀ اثر پرېوځى؟ او کۀ تۀ بار بار غلطيانې کوې، نو تۀ به د هغۀ څۀ وکړې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12739, 'Job 35:7', 'Job', 35, 7, '&nbsp;کۀ تۀ صادق يې، نو دې نه هغۀ ته څۀ فائده ده؟ خُدائ پاک ته ستا د يو څيز ضرورت هم نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12740, 'Job 35:8', 'Job', 35, 8, '&nbsp;ستا بدعملى صرف ستا په شان بنى آدم باندې اثر کوى، او ستا ښۀ عمل هم صرف په نورو بنيادمو اثر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12741, 'Job 35:9', 'Job', 35, 9, '&nbsp;د ظلمونو د زياتېدو په وجه خلق فرياد کوى، او د زورَورو د ظلم په وجه د مدد دپاره چغې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12742, 'Job 35:10', 'Job', 35, 10, '&nbsp;خو هيڅ څوک دا نۀ وائى چې خُدائ پاک زما پېدا کوونکے چرته دے؟ څوک چې د غم په وخت هم په خولۀ باندې سرودونه راولى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12743, 'Job 35:11', 'Job', 35, 11, '&nbsp;هغه مونږ ته د دُنيا د ځناورو نه زياته ښودنه کوى، او مونږ د هوا د مارغانو نه زيات هوښياروى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12744, 'Job 35:12', 'Job', 35, 12, '&nbsp;چې کله بدعمله فرياد کوى، نو خُدائ پاک د هغوئ د غرور په وجه جواب نۀ ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12745, 'Job 35:13', 'Job', 35, 13, '&nbsp;په حقيقت کښې خُدائ پاک بې‌مقصده فرياد نۀ اورى، او نۀ قادر خُدائ دې ته څۀ توجو ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12746, 'Job 35:14', 'Job', 35, 14, '&nbsp;تاسو وايئ چې تاسو خُدائ پاک نۀ وينئ، خو کۀ تاسو لږ صبر وکړئ نو هغه به د اِنصاف نه کار واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12747, 'Job 35:15', 'Job', 35, 15, '&nbsp;تاسو وايئ چې خُدائ پاک په غصه کښې سزا نۀ ورکوى، او د بدعملۍ پرواه نۀ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12748, 'Job 35:16', 'Job', 35, 16, '&nbsp;ايُوبه، تۀ فضول خبرې کوې، او لکه د يو بې‌وقوف په شان خبرې کوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12749, 'Job 36:1', 'Job', 36, 1, '&nbsp;اليهُو خپله خبره جارى وساتله او وې وئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12750, 'Job 36:2', 'Job', 36, 2, '&nbsp;”ما ته لږ صبر وکړئ، نو زۀ به تاسو ته حقيقت وښايم، ځکه چې زۀ د خُدائ پاک په صفايئ کښې څۀ وئيل غواړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12751, 'Job 36:3', 'Job', 36, 3, '&nbsp;زۀ به د خپل ډېر عِلم نه کار واخلم، چې دا ثابت کړم چې زما خالِق د اِنصاف مالِک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12752, 'Job 36:4', 'Job', 36, 4, '&nbsp;په حقيقت کښې زما خبرې غلطې نۀ دى، څوک چې ستا په وړاندې ولاړ دے هغه د اُستاذانو اُستاذ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12753, 'Job 36:5', 'Job', 36, 5, '&nbsp;خُدائ پاک بې‌شکه لوئ دے او د هيچا نه نفرت نۀ کوى، داسې يو عِلم هم نشته چې هغه يې نۀ لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12754, 'Job 36:6', 'Job', 36, 6, '&nbsp;هغه بدعمله خلق ژوندى نۀ پرېږدى، خو مظلومانو له خپل حق ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12755, 'Job 36:7', 'Job', 36, 7, '&nbsp;هغه د صادقانو حفاظت کوى، او د بادشاهانو سره يې په تخت کښېنوى او د تل دپاره عزت ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12756, 'Job 36:8', 'Job', 36, 8, '&nbsp;خو کۀ خلق په زنځيرونو کښې تړلے شوى وى او د ظلم په تارونو کښې ګېر شوى وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12757, 'Job 36:9', 'Job', 36, 9, '&nbsp;نو هغه ورته د هغوئ خپل عمل ښائى، او هغه غلطيانې ورته ښائى، چې کومې هغوئ په فخر سره کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12758, 'Job 36:10', 'Job', 36, 10, '&nbsp;هغه اصُولو ته يې پام راګرځوى، او حُکم ورکوى چې د بدو نه توبه وباسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12759, 'Job 36:11', 'Job', 36, 11, '&nbsp;کۀ هغوئ ورته توجو ورکړى او د هغۀ خِدمت وکړى، نو هغوئ به په مالدارۍ کښې خپلې ورځې پوره کړى، او په خوشحالۍ کښې به خپل کالونه پوره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12760, 'Job 36:12', 'Job', 36, 12, '&nbsp;خو کۀ هغوئ دې ته توجو ورنۀ کړى، نو هغوئ به په جهالت کښې هلاک شى او د خاورو د لاندې به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12761, 'Job 36:13', 'Job', 36, 13, '&nbsp;کوم خلق چې د خُدائ پاک نه منکر وى او هر وخت په غصه کښې وى، چې کله هغوئ ته سزا هم ملاويږى نو هغوئ د مدد دپاره دُعا نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12762, 'Job 36:14', 'Job', 36, 14, '&nbsp;هغوئ په ځوانۍ کښې مړۀ شى، او د هغوئ ژوند په زناکارۍ کښې ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12763, 'Job 36:15', 'Job', 36, 15, '&nbsp;خو هغه مظلومان د ظلم نه بچ کوى، او د مصيبتونو په وخت کښې ورته خپل ځان څرګندوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12764, 'Job 36:16', 'Job', 36, 16, '&nbsp;ايُوبه، خُدائ پاک دې تا د خطرې نه وباسى، او هغه ځائ ته دې بوځى چرته چې غم نۀ وى. هغه ستا په دسترخوان باندې ښۀ ښۀ خوراکونه کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12765, 'Job 36:17', 'Job', 36, 17, '&nbsp;خو د نورو بدعملو په شان به پوره سزا تا ته ملاويږى، تۀ په عدالت او اِنصاف کښې راګېر يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12766, 'Job 36:18', 'Job', 36, 18, '&nbsp;خبردار چې رشوت دې دوکه نۀ کړى، او دولت دې بې‌لارې نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12767, 'Job 36:19', 'Job', 36, 19, '&nbsp;ستا دولت او ستا طاقت ټول به تا د تکليف نه بچ کړى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12768, 'Job 36:20', 'Job', 36, 20, '&nbsp;د شپې د راتلو خواهش مۀ کوه، د هغه وخت چې کله قومونه تباه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12769, 'Job 36:21', 'Job', 36, 21, '&nbsp;خبردار، چې د بدعملۍ طرف ته وانۀ وړې، خُدائ پاک ځکه په تکليف کړے يې چې په بدعملۍ کښې آخته نۀ شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12770, 'Job 36:22', 'Job', 36, 22, '&nbsp;ياد ساته چې د خُدائ پاک طاقت څومره لوئ دے، او هغه د ټولو نه عظيم اُستاذ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12771, 'Job 36:23', 'Job', 36, 23, '&nbsp;هيڅوک خُدائ پاک ته دا نۀ شى وئيلے چې هغه به څۀ کوى، او څوک ورته وئيلے شى چې تا غلط کار کړے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12772, 'Job 36:24', 'Job', 36, 24, '&nbsp;څۀ چې هغه کوى په هغې تل د هغۀ تعريف کيږى. تۀ هم د هغۀ ثناء صِفت کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12773, 'Job 36:25', 'Job', 36, 25, '&nbsp;ټولو خلقو دې ته کتلى دى، هر يو کس د لرې نه دې ته ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12774, 'Job 36:26', 'Job', 36, 26, '&nbsp;بې‌شکه خُدائ پاک لوئ دے او مونږ د هغۀ د لويئ اندازه هم نۀ شُو لګولے، د هغۀ د کالونو شمېر نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12775, 'Job 36:27', 'Job', 36, 27, '&nbsp;ځکه چې هغه نمى اوچتوى، او په باران يې بدلوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12776, 'Job 36:28', 'Job', 36, 28, '&nbsp;هغه وريځې جوړوى او په هر چا باران راوروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12777, 'Job 36:29', 'Job', 36, 29, '&nbsp;څوک د وريځو په خورېدو باندې پوهيږى، او د آسمان په تندر باندې پوهيږى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12778, 'Job 36:30', 'Job', 36, 30, '&nbsp;ګوره، هغه په آسمان کښې برېښنا راولى خو د سمندر بېخ کښې تيارۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12779, 'Job 36:31', 'Job', 36, 31, '&nbsp;ځکه چې د دې په ذريعه هغه په خلقو حکومت کوى، او هغه خلقو له بې‌حسابه خوراک ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12780, 'Job 36:32', 'Job', 36, 32, '&nbsp;هغه برېښنا په خپلو لاسونو کښې ساتى، او حُکم ورکوى چې نښه وولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12781, 'Job 36:33', 'Job', 36, 33, '&nbsp;د هغۀ د تندر آواز داسې وائى، چې هغه غېرتى دے او د ګناه خِلاف غصه لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12782, 'Job 37:1', 'Job', 37, 1, '&nbsp;په دې باندې هم زما زړۀ درزيږى، او ټوپونه وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12783, 'Job 37:2', 'Job', 37, 2, '&nbsp;واورئ، واورئ، د خُدائ پاک د تندر آواز واورئ او د غړمبا آواز واورئ چې د هغۀ د خولې نه راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12784, 'Job 37:3', 'Job', 37, 3, '&nbsp;د ټول آسمان لاندې هغه دا پړق وهى، او د هغۀ رڼا د دُنيا ګوټونو ته رسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12785, 'Job 37:4', 'Job', 37, 4, '&nbsp;بيا د هغۀ آواز شور جوړ کړى، او د هغۀ د تندر آوازونه د شان او شوکت سره راشى، کله چې د هغۀ آواز واورېدے شى نو هغه رڼاګانې نۀ ايساروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12786, 'Job 37:5', 'Job', 37, 5, '&nbsp;خُدائ پاک د خپل آواز سره زبردست تندر راولى، هغه داسې لوئ کارونه کوى چې مونږ پرې نۀ پوهيږو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12787, 'Job 37:6', 'Job', 37, 6, '&nbsp;ځکه چې هغه واورې ته وائى چې په زمکه وورېږه، او باران ته وائى چې وورېږه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12788, 'Job 37:7', 'Job', 37, 7, '&nbsp;نو هر يو کس خپل کار بس کړى چې د هغۀ طاقت وګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12789, 'Job 37:8', 'Job', 37, 8, '&nbsp;بيا ځنګلى ځناور خپلو پناه ګاهو ته لاړ شى او په خپلو غارونو کښې پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12790, 'Job 37:9', 'Job', 37, 9, '&nbsp;د جنوب طرف نه طوفانى هوا راځى، او د شمال طرف نه د سختې هوا نه يخنى راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12791, 'Job 37:10', 'Job', 37, 10, '&nbsp;د خُدائ پاک ساه د اوبو نه واوره جوړوى، او ډېرې اوبۀ په واوره باندې بدلې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12792, 'Job 37:11', 'Job', 37, 11, '&nbsp;هغه وريځ د نمۍ نه ډکوى، او په وريځو کښې برېښنا پړقوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12793, 'Job 37:12', 'Job', 37, 12, '&nbsp;کله چې دا د خُدائ پاک په مرضۍ چليږى نو دا په ټوله دُنيا کښې د خُدائ پاک هر يو حُکم پوره کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12794, 'Job 37:13', 'Job', 37, 13, '&nbsp;هغه دا کارونه ځکه کوى چې خلقو ته په کښې تکليف مِلاو شى يا کۀ نۀ ختمېدونکې مينه ورته ښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12795, 'Job 37:14', 'Job', 37, 14, '&nbsp;اے ايُوبه، دا واوره، ودرېږه او د خُدائ پاک په دې عجيبه عجيبه کارونو باندې سوچ وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12796, 'Job 37:15', 'Job', 37, 15, '&nbsp;تا ته پته شته څۀ چې هغه طوفان څنګه قابو کوى، او د خپلې وريځې نه رڼا څنګه پړقوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12797, 'Job 37:16', 'Job', 37, 16, '&nbsp;تا ته پته شته چې وريځې په آسمان کښې څنګه روانې وى، دا د هغه چا عجيبه کارونه دى چې عِلم يې پوره دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12798, 'Job 37:17', 'Job', 37, 17, '&nbsp;کله چې تاسو په خپلو جامو کښې سوزئ او د جنوب طرف ته هوا بنده شى او يو څيز هم نۀ خوځيږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12799, 'Job 37:18', 'Job', 37, 18, '&nbsp;هغه په آسمانونو کښې سترګې برېښوونکې رڼا ځلوى. ولې تاسو هغه شان کولے شئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12800, 'Job 37:19', 'Job', 37, 19, '&nbsp;مونږ ته ووايئ چې هغۀ ته څۀ ووايو، زمونږ دماغ کار نۀ کوى چې خپله خبره بيان کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');